PORKOLT_SIDES = [("nokedli", 200), ("petrezselymes_burgonya", 200), ("parolt_rizs", 180)]


def sides(*names):
    """alias_side phrases 'X nokedlivel/galuskával/krumplival/rizzsel' for each dish name."""
    d = {}
    for n in names:
        d[f"{n} nokedlivel"] = "nokedli"
        d[f"{n} galuskával"] = "nokedli"
        d[f"{n} krumplival"] = "petrezselymes_burgonya"
        d[f"{n} rizzsel"] = "parolt_rizs"
    return d


